from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

from uremote import uRemote

# Set up.
ur = uRemote('A')
card_id = 0
confidence = 0
me = Motor(Port.E, Direction.COUNTERCLOCKWISE)
mf = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(me, mf, 89, 114)


# The main program starts here.
while True:
    card_id, confidence = ur.card() or [0] * 2
    if card_id == 15:
        # Forward
        drive_base.straight(100)
        wait(1000)
    elif card_id == 16:
        # Back
        drive_base.straight(-100)
        wait(1000)
    elif card_id == 18:
        # Right
        drive_base.turn(90)
        wait(1000)
    elif card_id == 17:
        # Left
        drive_base.turn(-90)
        wait(1000)
    elif card_id > 0:
        print(card_id)
    else:
        pass
